sys_script_client.script:
function onLoad() {
  // Only auto-populate when creating a NEW line
  if (!g_form.isNewRecord()) return;

  // Fill only if those fields are empty
  if (g_scratchpad.emp && !g_form.getValue('employee_name')) {
    g_form.setValue('employee_name', g_scratchpad.emp);              // reference to sys_user
  }
  if (g_scratchpad.emp_email && !g_form.getValue('employee_email')) {
    g_form.setValue('employee_email', g_scratchpad.emp_email);       // string
  }
  if (g_scratchpad.manager && !g_form.getValue('manager')) {
    g_form.setValue('manager', g_scratchpad.manager);                // reference to sys_user
  }
  if (g_scratchpad.manager_email && !g_form.getValue('manager_email')) {
    g_form.setValue('manager_email', g_scratchpad.manager_email);    // string
  }
}
